import unittest
from preferences import preferences

class PreferencesTests(unittest.TestCase):
    def test_a_dark_selection(self):
        p = preferences()
        p["theme"] = "dark"
        self.assertEqual(p["theme"], "dark")

    def test_b_default(self):
        self.assertEqual(preferences()["theme"], "light")
